import org.springframework.boot.loader.tools.LibraryScope;
import org.springframework.boot.loader.tools.Repackager;

import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

public class Repack {

    public static void main(String[] args) throws Exception {
        File source = new File(args[0]);
        File dest = new File(args[1]);
        List<File> libs = new ArrayList<>();
        for (String line : Files.readAllLines(Path.of(args[2]))) {
            if (!line.isBlank()) {
                libs.add(new File(line.trim()));
            }
        }
        Repackager repackager = new Repackager(source);
        repackager.setMainClass("com.taskbridge.worker.TaskBridgeApplication");
        repackager.repackage(dest, callback -> {
            for (File lib : libs) {
                callback.library(new Library(lib, LibraryScope.RUNTIME, false));
            }
        });
        System.out.println("Repackaged " + source.getName() + " -> " + dest.getName()
                + " with " + libs.size() + " libraries");
    }
}
